"use client";
import { assets } from '@/assets/assets';
import Title from '@/components/Title';
import Image from 'next/image';
import React, { useState } from 'react';

const Page = () => {
 const [image, setImage] = useState({
  1: null,
  2: null,
  3: null,
  4: null
 });

 const [inputs, setInputs] = useState({
  roomType: "",
  pricePerNight: 0,
  amenities: {
   'Free WiFi': false,
   'Free Breakfast': false,
   'Mountain View': false,
   'Pool Access': false,


  }
 })
 return (
  <form>
   <Title
    title='Add Room'
    subtitle='Fill in the details carefully and accurate room details, pricing, and amenities, to enhance the user booking experience.'
    aling='left'
    front='outfit'
   />
   <p className='text-gray-800 mt-10'>Images</p>
   <div className='grid grid-cols-2 sm:flex gap-4 my-2 flex-rap'>
    {Object.keys(image).map((key) => (
     <label key={key} htmlFor={`roomImage${key}`}>
      <Image src={image[key] ? URL.createObjectURL(image[key]) : assets.uploadArea} alt="room" width={100} height={100} className='max-h-13 cursor-pointer opacity-80' />
      <input type='file' accept='image/*' id={`roomImage${key}`} hidden onChange={(e) => setImage({ ...image, [key]: e.target.files[0] })} />
     </label>
    ))}
   </div>

   <div className='w-full flex max-sm:flex-col sm:gap-4 mt-4'>
    <div className='flex-1 max-w-48'>
     <p className='text-gray-800 mt-4'>
      Room Type
     </p>
     <select value={inputs.roomType} onChange={e => setInputs({ ...inputs, roomType: e.target.value })} className='border opacity-70 border-gray-300 mt-1 rounded p-2 w-full'>
      <option value=''>Select Room Type</option>
      <option value='Single Bed'>Single Bed</option>
      <option value='Double Bed'>Double Bed</option>
      <option value='Luxury Room'>Luxury Room</option>
      <option value='Family Suite'>Family Suite</option>
     </select>
    </div>

    <div className=''>
     <p className='mt-4 text-gray-800'>
      Price
      <span className='text-xs'>
       /night
      </span>
     </p>
     <input type="number" placeholder='0' className='border border-gray-300 mt-1 rounded p-2 w-24' value={inputs.pricePerNight} onChange={e => setInputs({ ...inputs, pricePerNight: e.target.value })} />
    </div>
   </div>
   <p className='text-gray-800 mt-4'>
    Amenities
   </p>
   <div className='flex flex-col flex-wrap mt-1 text-gray-400 max-w-sm'>
    {Object.keys(inputs.amenities).map((amenity, index) => (
     <div key={index}>
      <input type='checkbox'  id={`amenities${index + 1}`} checked={inputs.amenities[amenity]} onChange={() => setInputs({ ...inputs, amenities: { ...inputs.amenities, [amenity]: !inputs.amenities[amenity] } })} className='cursor-pointer' />
      <label htmlFor={`amenities${index + 1}`} className='ml-2'>{amenity}</label>
     </div>
    ))}
   </div>
   <button className='bg-primary  text-white py-2 px-8 rounded mt-8 cursor-pointer transition-all duration-300'>Add Room</button>
  </form>
 );
}

export default Page;
